1	import { useState, useCallback } from "react";
2	import { useNavigate } from "react-router-dom";
3	import { useDebounce } from "@/hooks/use-debounce";
4	import {
5	  Search,
6	  Users as UsersIcon,
7	  ChevronUp,
8	  ChevronDown,
9	  ChevronsUpDown,
10	  ChevronLeft,
11	  ChevronRight,
12	  Download,
13	  Loader2,
14	  X,
15	} from "lucide-react";
16	import { PageHeader } from "@/components/shared/PageHeader";
17	import { EmptyState } from "@/components/shared/EmptyState";
18	import { Input } from "@/components/ui/input";
19	import { Button } from "@/components/ui/button";
20	import { Badge } from "@/components/ui/badge";
21	import { Skeleton } from "@/components/ui/skeleton";
22	import { Checkbox } from "@/components/ui/checkbox";
23	import {
24	  Select,
25	  SelectContent,
26	  SelectItem,
27	  SelectTrigger,
28	  SelectValue,
29	} from "@/components/ui/select";
30	import {
31	  Table,
32	  TableBody,
33	  TableCell,
34	  TableHead,
35	  TableHeader,
36	  TableRow,
37	} from "@/components/ui/table";
38	import {
39	  AlertDialog,
40	  AlertDialogAction,
41	  AlertDialogCancel,
42	  AlertDialogContent,
43	  AlertDialogDescription,
44	  AlertDialogFooter,
45	  AlertDialogHeader,
46	  AlertDialogTitle,
47	} from "@/components/ui/alert-dialog";
48	import { useAdminUsers, useExportUsers, type AdminUsersFilter } from "@/hooks/admin/use-admin-users";
49	import { useBulkChangePlan, useBulkResetScans } from "@/hooks/admin/use-admin-actions";
50	import type { ProfileRow } from "@/types/database";
51	import type { PlanType, UserRole } from "@/types/index";
52	import { format } from "date-fns";
53	
54	const PLAN_BADGE_CLASSES: Record<PlanType, string> = {
55	  free: "bg-muted/50 text-foreground/80 border-0",
56	  pro: "bg-indigo-100 text-indigo-700 border-0",
57	  agency: "bg-purple-100 text-purple-700 border-0",
58	};
59	
60	const ROLE_BADGE_CLASSES: Record<UserRole, string> = {
61	  user: "bg-muted/50 text-foreground/80 border-0",
62	  admin: "bg-amber-100 text-amber-700 border-0",
63	  super_admin: "bg-red-100 text-red-700 border-0",
64	};
65	
66	type SortableColumn = "email" | "full_name" | "plan" | "scans_used" | "role" | "created_at";
67	
68	function SortIcon({ column, sortColumn, sortAsc }: {
69	  column: SortableColumn;
70	  sortColumn: SortableColumn;
71	  sortAsc: boolean;
72	}) {
73	  if (sortColumn !== column) return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 text-muted-foreground/40" />;
74	  return sortAsc
75	    ? <ChevronUp className="ml-1 h-3.5 w-3.5 text-primary" />
76	    : <ChevronDown className="ml-1 h-3.5 w-3.5 text-primary" />;
77	}
78	
79	function TableSkeleton() {
80	  return (
81	    <>
82	      {Array.from({ length: 8 }).map((_, i) => (
83	        <TableRow key={i}>
84	          {Array.from({ length: 8 }).map((__, j) => (
85	            <TableCell key={j}>
86	              <Skeleton className="h-4 w-full max-w-[120px]" />
87	            </TableCell>
88	          ))}
89	        </TableRow>
90	      ))}
91	    </>
92	  );
93	}
94	
95	const PAGE_SIZE = 20;
96	
97	function SortableHeader({
98	  column,
99	  label,
100	  sortColumn,
101	  sortAsc,
102	  onSort,
103	}: {
104	  column: SortableColumn;
105	  label: string;
106	  sortColumn: SortableColumn;
107	  sortAsc: boolean;
108	  onSort: (col: SortableColumn) => void;
109	}) {
110	  return (
111	    <TableHead
112	      className="cursor-pointer select-none whitespace-nowrap"
113	      onClick={() => onSort(column)}
114	      aria-sort={
115	        sortColumn === column ? (sortAsc ? "ascending" : "descending") : "none"
116	      }
117	    >
118	      <span className="inline-flex items-center">
119	        {label}
120	        <SortIcon column={column} sortColumn={sortColumn} sortAsc={sortAsc} />
121	      </span>
122	    </TableHead>
123	  );
124	}
125	
126	export default function AdminUsers() {
127	  const navigate = useNavigate();
128	  const [search, setSearch] = useState("");
129	  const [planFilter, setPlanFilter] = useState<PlanType | "">("");
130	  const [roleFilter, setRoleFilter] = useState<UserRole | "">("");
131	  const [page, setPage] = useState(0);
132	  const [sortColumn, setSortColumn] = useState<SortableColumn>("created_at");
133	  const [sortAsc, setSortAsc] = useState(false);
134	
135	  // Bulk selection state
136	  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
137	  const [bulkPlan, setBulkPlan] = useState<PlanType | "">("");
138	  const [bulkPlanDialogOpen, setBulkPlanDialogOpen] = useState(false);
139	  const [pendingBulkPlan, setPendingBulkPlan] = useState<PlanType | null>(null);
140	
141	  const debouncedSearch = useDebounce(search, 350);
142	
143	  const filter: AdminUsersFilter = {
144	    search: debouncedSearch || undefined,
145	    plan: planFilter || undefined,
146	    role: roleFilter || undefined,
147	  };
148	
149	  const { data, isLoading, isError } = useAdminUsers({
150	    page,
151	    pageSize: PAGE_SIZE,
152	    filter,
153	    sortColumn: sortColumn as keyof ProfileRow,
154	    sortAsc,
155	  });
156	
157	  const exportUsersQuery = useExportUsers(filter);
158	  const [isExporting, setIsExporting] = useState(false);
159	
160	  const bulkChangePlan = useBulkChangePlan();
161	  const bulkResetScans = useBulkResetScans();
162	
163	  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;
164	  const visibleUsers = data?.users ?? [];
165	  const allVisibleSelected = visibleUsers.length > 0 && visibleUsers.every((u) => selectedIds.has(u.id));
166	
167	  const handleSort = useCallback((col: SortableColumn) => {
168	    setSortColumn((prev) => {
169	      if (prev === col) {
170	        setSortAsc((asc) => !asc);
171	        return prev;
172	      }
173	      setSortAsc(true);
174	      return col;
175	    });
176	    setPage(0);
177	  }, []);
178	
179	  const toggleSelect = useCallback((id: string) => {
180	    setSelectedIds((prev) => {
181	      const next = new Set(prev);
182	      if (next.has(id)) next.delete(id);
183	      else next.add(id);
184	      return next;
185	    });
186	  }, []);
187	
188	  const toggleSelectAll = useCallback(() => {
189	    if (allVisibleSelected) {
190	      setSelectedIds((prev) => {
191	        const next = new Set(prev);
192	        visibleUsers.forEach((u) => next.delete(u.id));
193	        return next;
194	      });
195	    } else {
196	      setSelectedIds((prev) => {
197	        const next = new Set(prev);
198	        visibleUsers.forEach((u) => next.add(u.id));
199	        return next;
200	      });
201	    }
202	  }, [allVisibleSelected, visibleUsers]);
203	
204	  const handleBulkPlanChange = (plan: PlanType | "") => {
205	    if (!plan) return;
206	    setBulkPlan(plan);
207	    setPendingBulkPlan(plan as PlanType);
208	    setBulkPlanDialogOpen(true);
209	  };
210	
211	  const confirmBulkPlanChange = () => {
212	    if (!pendingBulkPlan) return;
213	    bulkChangePlan.mutate(
214	      { userIds: Array.from(selectedIds), plan: pendingBulkPlan },
215	      {
216	        onSuccess: () => {
217	          setSelectedIds(new Set());
218	          setBulkPlan("");
219	          setPendingBulkPlan(null);
220	          setBulkPlanDialogOpen(false);
221	        },
222	      }
223	    );
224	  };
225	
226	  const handleBulkResetScans = () => {
227	    bulkResetScans.mutate(
228	      { userIds: Array.from(selectedIds) },
229	      {
230	        onSuccess: () => setSelectedIds(new Set()),
231	      }
232	    );
233	  };
234	
235	  const handleExport = async () => {
236	    setIsExporting(true);
237	    try {
238	      const result = await exportUsersQuery.refetch();
239	      if (!result.data) return;
240	      const blob = new Blob([result.data], { type: "text/csv" });
241	      const url = URL.createObjectURL(blob);
242	      const a = document.createElement("a");
243	      a.href = url;
244	      a.download = `users-${format(new Date(), "yyyy-MM-dd")}.csv`;
245	      a.click();
246	      URL.revokeObjectURL(url);
247	    } finally {
248	      setIsExporting(false);
249	    }
250	  };
251	
252	  const selectedCount = selectedIds.size;
253	
254	  return (
255	    <div className="space-y-6">
256	      <div className="flex items-center justify-between gap-4">
257	        <PageHeader
258	          title="Users"
259	          description={
260	            data ? `${data.total.toLocaleString()} total users` : "All registered users"
261	          }
262	        />
263	        <Button
264	          variant="outline"
265	          size="sm"
266	          onClick={handleExport}
267	          disabled={isExporting}
268	          className="shrink-0"
269	        >
270	          {isExporting ? (
271	            <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
272	          ) : (
273	            <Download className="mr-2 h-3.5 w-3.5" />
274	          )}
275	          {isExporting ? "Exporting…" : "Export CSV"}
276	        </Button>
277	      </div>
278	
279	      {/* Filters */}
280	      <div className="flex flex-wrap items-center gap-3">
281	        <div className="relative flex-1 min-w-[200px] max-w-xs">
282	          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
283	          <Input
284	            placeholder="Search by email or name..."
285	            value={search}
286	            onChange={(e) => { setSearch(e.target.value); setPage(0); }}
287	            className="pl-9"
288	            aria-label="Search users"
289	          />
290	        </div>
291	
292	        <Select
293	          value={planFilter || "all"}
294	          onValueChange={(v) => {
295	            setPlanFilter((v === "all" ? "" : v) as PlanType | "");
296	            setPage(0);
297	          }}
298	        >
299	          <SelectTrigger className="w-[130px]" aria-label="Filter by plan">
300	            <SelectValue placeholder="All plans" />
301	          </SelectTrigger>
302	          <SelectContent>
303	            <SelectItem value="all">All plans</SelectItem>
304	            <SelectItem value="free">Free</SelectItem>
305	            <SelectItem value="pro">Pro</SelectItem>
306	            <SelectItem value="agency">Agency</SelectItem>
307	          </SelectContent>
308	        </Select>
309	
310	        <Select
311	          value={roleFilter || "all"}
312	          onValueChange={(v) => {
313	            setRoleFilter((v === "all" ? "" : v) as UserRole | "");
314	            setPage(0);
315	          }}
316	        >
317	          <SelectTrigger className="w-[150px]" aria-label="Filter by role">
318	            <SelectValue placeholder="All roles" />
319	          </SelectTrigger>
320	          <SelectContent>
321	            <SelectItem value="all">All roles</SelectItem>
322	            <SelectItem value="user">User</SelectItem>
323	            <SelectItem value="admin">Admin</SelectItem>
324	            <SelectItem value="super_admin">Super Admin</SelectItem>
325	          </SelectContent>
326	        </Select>
327	
328	        {(debouncedSearch || planFilter || roleFilter) && (
329	          <Button
330	            variant="ghost"
331	            size="sm"
332	            onClick={() => {
333	              setSearch("");
334	              setPlanFilter("");
335	              setRoleFilter("");
336	              setPage(0);
337	            }}
338	          >
339	            Clear filters
340	          </Button>
341	        )}
342	      </div>
343	
344	      {/* Bulk action bar */}
345	      {selectedCount > 0 && (
346	        <div className="flex flex-wrap items-center gap-3 bg-indigo-50 border border-indigo-100 rounded-xl px-4 py-2.5">
347	          <span className="text-sm font-medium text-indigo-700">
348	            {selectedCount} {selectedCount === 1 ? "user" : "users"} selected
349	          </span>
350	
351	          <div className="flex items-center gap-2 ml-auto flex-wrap">
352	            {/* Change plan dropdown */}
353	            <Select
354	              value={bulkPlan}
355	              onValueChange={(v) => handleBulkPlanChange(v as PlanType)}
356	            >
357	              <SelectTrigger className="w-[150px] h-8 text-xs border-indigo-200 bg-white">
358	                <SelectValue placeholder="Change plan…" />
359	              </SelectTrigger>
360	              <SelectContent>
361	                <SelectItem value="free">Set to Free</SelectItem>
362	                <SelectItem value="pro">Set to Pro</SelectItem>
363	                <SelectItem value="agency">Set to Agency</SelectItem>
364	              </SelectContent>
365	            </Select>
366	
367	            {/* Reset scan count */}
368	            <Button
369	              variant="outline"
370	              size="sm"
371	              className="h-8 text-xs border-indigo-200 text-indigo-700 hover:bg-indigo-100"
372	              onClick={handleBulkResetScans}
373	              disabled={bulkResetScans.isPending}
374	            >
375	              {bulkResetScans.isPending ? (
376	                <Loader2 className="mr-1.5 h-3 w-3 animate-spin" />
377	              ) : null}
378	              Reset Scan Count
379	            </Button>
380	
381	            {/* Deselect all */}
382	            <Button
383	              variant="ghost"
384	              size="sm"
385	              className="h-8 text-xs text-indigo-600 hover:bg-indigo-100"
386	              onClick={() => setSelectedIds(new Set())}
387	            >
388	              <X className="mr-1 h-3 w-3" />
389	              Deselect All
390	            </Button>
391	          </div>
392	        </div>
393	      )}
394	
395	      {/* Table */}
396	      <div className="rounded-xl border border-border/50 overflow-hidden overflow-x-auto scrollbar-thin">
397	        <Table>
398	          <TableHeader>
399	            <TableRow className="bg-muted/40 hover:bg-muted/40">
400	              {/* Select all checkbox */}
401	              <TableHead className="w-10">
402	                <Checkbox
403	                  checked={allVisibleSelected}
404	                  onCheckedChange={toggleSelectAll}
405	                  aria-label="Select all visible users"
406	                  disabled={isLoading || visibleUsers.length === 0}
407	                />
408	              </TableHead>
409	              <SortableHeader column="email" label="Email" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
410	              <SortableHeader column="full_name" label="Name" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
411	              <SortableHeader column="plan" label="Plan" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
412	              <SortableHeader column="scans_used" label="Scans Used" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
413	              <SortableHeader column="role" label="Role" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
414	              <SortableHeader column="created_at" label="Signed Up" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
415	              <TableHead className="w-10" />
416	            </TableRow>
417	          </TableHeader>
418	          <TableBody>
419	            {isLoading ? (
420	              <TableSkeleton />
421	            ) : isError ? (
422	              <TableRow>
423	                <TableCell
424	                  colSpan={8}
425	                  className="py-10 text-center text-sm text-red-600"
426	                >
427	                  Failed to load users. Check your admin permissions.
428	                </TableCell>
429	              </TableRow>
430	            ) : data?.users.length === 0 ? (
431	              <TableRow>
432	                <TableCell colSpan={8} className="p-0">
433	                  <EmptyState
434	                    icon={UsersIcon}
435	                    title="No users found"
436	                    description="Try adjusting your search or filters."
437	                  />
438	                </TableCell>
439	              </TableRow>
440	            ) : (
441	              data?.users.map((user) => {
442	                const isSelected = selectedIds.has(user.id);
443	                return (
444	                  <TableRow
445	                    key={user.id}
446	                    className={`hover:bg-muted/40 transition-colors ${isSelected ? "bg-indigo-50/50" : ""}`}
447	                  >
448	                    {/* Row checkbox */}
449	                    <TableCell
450	                      onClick={(e) => e.stopPropagation()}
451	                    >
452	                      <Checkbox
453	                        checked={isSelected}
454	                        onCheckedChange={() => toggleSelect(user.id)}
455	                        aria-label={`Select user ${user.email}`}
456	                      />
457	                    </TableCell>
458	
459	                    {/* Rest of row — click to navigate */}
460	                    <TableCell
461	                      className="font-mono text-xs text-muted-foreground cursor-pointer"
462	                      onClick={() => navigate(`/admin/users/${user.id}`)}
463	                    >
464	                      {user.email}
465	                    </TableCell>
466	                    <TableCell
467	                      className="text-sm font-medium cursor-pointer"
468	                      onClick={() => navigate(`/admin/users/${user.id}`)}
469	                    >
470	                      <div className="flex items-center gap-1.5">
471	                        {user.full_name || (
472	                          <span className="text-muted-foreground/50">—</span>
473	                        )}
474	                        {user.is_banned && (
475	                          <Badge className="bg-red-100 text-red-700 border-0 text-2xs px-1.5 py-0">
476	                            Banned
477	                          </Badge>
478	                        )}
479	                      </div>
480	                    </TableCell>
481	                    <TableCell
482	                      className="cursor-pointer"
483	                      onClick={() => navigate(`/admin/users/${user.id}`)}
484	                    >
485	                      <Badge
486	                        className={`text-xs px-2 py-0.5 capitalize ${
487	                          PLAN_BADGE_CLASSES[user.plan]
488	                        }`}
489	                      >
490	                        {user.plan}
491	                      </Badge>
492	                    </TableCell>
493	                    <TableCell
494	                      className="text-sm text-muted-foreground cursor-pointer"
495	                      onClick={() => navigate(`/admin/users/${user.id}`)}
496	                    >
497	                      {user.scans_used} / {user.scan_limit}
498	                    </TableCell>
499	                    <TableCell
500	                      className="cursor-pointer"
501	                      onClick={() => navigate(`/admin/users/${user.id}`)}
502	                    >
503	                      <Badge
504	                        className={`text-xs px-2 py-0.5 capitalize ${
505	                          ROLE_BADGE_CLASSES[user.role]
506	                        }`}
507	                      >
508	                        {user.role.replace("_", " ")}
509	                      </Badge>
510	                    </TableCell>
511	                    <TableCell
512	                      className="text-sm text-muted-foreground cursor-pointer"
513	                      onClick={() => navigate(`/admin/users/${user.id}`)}
514	                    >
515	                      {format(new Date(user.created_at), "MMM d, yyyy")}
516	                    </TableCell>
517	                    <TableCell>
518	                      <ChevronRight className="h-4 w-4 text-muted-foreground/40" />
519	                    </TableCell>
520	                  </TableRow>
521	                );
522	              })
523	            )}
524	          </TableBody>
525	        </Table>
526	      </div>
527	
528	      {/* Pagination */}
529	      {totalPages > 1 && (
530	        <div className="flex items-center justify-between">
531	          <p className="text-sm text-muted-foreground">
532	            Page {page + 1} of {totalPages} ({data?.total.toLocaleString()} users)
533	          </p>
534	          <div className="flex items-center gap-2">
535	            <Button
536	              variant="outline"
537	              size="sm"
538	              onClick={() => setPage((p) => Math.max(0, p - 1))}
539	              disabled={page === 0}
540	              aria-label="Previous page"
541	            >
542	              <ChevronLeft className="h-4 w-4" />
543	            </Button>
544	            <Button
545	              variant="outline"
546	              size="sm"
547	              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
548	              disabled={page >= totalPages - 1}
549	              aria-label="Next page"
550	            >
551	              <ChevronRight className="h-4 w-4" />
552	            </Button>
553	          </div>
554	        </div>
555	      )}
556	
557	      {/* Bulk plan change confirmation dialog */}
558	      <AlertDialog open={bulkPlanDialogOpen} onOpenChange={setBulkPlanDialogOpen}>
559	        <AlertDialogContent>
560	          <AlertDialogHeader>
561	            <AlertDialogTitle>Change plan for {selectedCount} users?</AlertDialogTitle>
562	            <AlertDialogDescription>
563	              This will change the plan to{" "}
564	              <strong className="capitalize">{pendingBulkPlan}</strong> for all{" "}
565	              {selectedCount} selected users and update their scan limits
566	              accordingly. This affects their billing access.
567	            </AlertDialogDescription>
568	          </AlertDialogHeader>
569	          <AlertDialogFooter>
570	            <AlertDialogCancel onClick={() => { setBulkPlan(""); setPendingBulkPlan(null); }}>
571	              Cancel
572	            </AlertDialogCancel>
573	            <AlertDialogAction
574	              onClick={confirmBulkPlanChange}
575	              disabled={bulkChangePlan.isPending}
576	              className="bg-indigo-600 hover:bg-indigo-700"
577	            >
578	              {bulkChangePlan.isPending ? (
579	                <>
580	                  <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
581	                  Updating…
582	                </>
583	              ) : (
584	                `Update ${selectedCount} Users`
585	              )}
586	            </AlertDialogAction>
587	          </AlertDialogFooter>
588	        </AlertDialogContent>
589	      </AlertDialog>
590	    </div>
591	  );
592	}
