1	import { useState, useCallback } from "react";
2	import { useDebounce } from "@/hooks/use-debounce";
3	import {
4	  ScanLine,
5	  Search,
6	  ChevronLeft,
7	  ChevronRight,
8	  ExternalLink,
9	  Trash2,
10	  MoreHorizontal,
11	  AlertTriangle,
12	  CheckCircle2,
13	  Clock,
14	  Loader2,
15	  ChevronUp,
16	  ChevronDown,
17	  ChevronsUpDown,
18	  RotateCcw,
19	} from "lucide-react";
20	import { PageHeader } from "@/components/shared/PageHeader";
21	import { EmptyState } from "@/components/shared/EmptyState";
22	import { KpiCard } from "@/components/shared/KpiCard";
23	import { Input } from "@/components/ui/input";
24	import { Button } from "@/components/ui/button";
25	import { Badge } from "@/components/ui/badge";
26	import { Skeleton } from "@/components/ui/skeleton";
27	import {
28	  Select,
29	  SelectContent,
30	  SelectItem,
31	  SelectTrigger,
32	  SelectValue,
33	} from "@/components/ui/select";
34	import {
35	  Table,
36	  TableBody,
37	  TableCell,
38	  TableHead,
39	  TableHeader,
40	  TableRow,
41	} from "@/components/ui/table";
42	import {
43	  DropdownMenu,
44	  DropdownMenuContent,
45	  DropdownMenuItem,
46	  DropdownMenuSeparator,
47	  DropdownMenuTrigger,
48	} from "@/components/ui/dropdown-menu";
49	import {
50	  AlertDialog,
51	  AlertDialogAction,
52	  AlertDialogCancel,
53	  AlertDialogContent,
54	  AlertDialogDescription,
55	  AlertDialogFooter,
56	  AlertDialogHeader,
57	  AlertDialogTitle,
58	} from "@/components/ui/alert-dialog";
59	import {
60	  useAdminScans,
61	  useAdminScanStats,
62	  useDeleteScan,
