232	
233	      {/* Pagination */}
234	      {totalPages > 1 && (
235	        <div className="flex items-center justify-between pt-2">
236	          <p className="text-sm text-muted-foreground">
237	            Page {page + 1} of {totalPages}
238	          </p>
239	          <div className="flex items-center gap-2">
240	            <Button
241	              variant="outline"
242	              size="sm"
243	              onClick={() => setPage((p) => Math.max(0, p - 1))}
244	              disabled={page === 0}
