const PILLAR_DEFINITIONS = [
  { key: "value_proposition", label: "Value Proposition" },
  { key: "cta_effectiveness", label: "CTA Effectiveness" },
  { key: "trust_signals", label: "Trust Signals" },
  { key: "visual_hierarchy", label: "Visual Hierarchy" },
