]

function StatusIndicator({ connected, label, note }: {
  connected: boolean | "unknown"
  label: string
  note?: string
}) {
  const icon =
    connected === true ? <CheckCircle2 className="h-4 w-4 text-green-500 shrink-0" /> :
    connected === false ? <XCircle className="h-4 w-4 text-red-500 shrink-0" /> :
    <AlertCircle className="h-4 w-4 text-amber-500 shrink-0" />

  const statusText = connected === true ? "Connected" : connected === false ? "Disconnected" : "Unknown"
  const statusClass = connected === true ? "text-green-600" : connected === false ? "text-red-600" : "text-amber-600"
  const badgeBg = connected === true ? "bg-green-100" : connected === false ? "bg-red-100" : "bg-amber-100"

  return (
    <div className="flex items-center justify-between py-2.5">
      <div className="flex items-center gap-2.5">
        {icon}
        <div>
          <p className="text-sm font-medium text-foreground">{label}</p>
          {note && <p className="text-xs text-muted-foreground">{note}</p>}
        </div>
      </div>
      <Badge className={`text-xs px-2 py-0.5 border-0 ${badgeBg} ${statusClass}`}>{statusText}</Badge>
    </div>
  )
}

function DbStatRow({ label, value, isLoading }: { label: string; value: number; isLoading: boolean }) {
  return (
    <div className="flex items-center justify-between py-2.5">
      <span className="text-sm text-muted-foreground">{label}</span>
      {isLoading ? (
        <Skeleton className="h-4 w-16" />
      ) : (
        <span className="text-sm font-semibold text-foreground tabular-nums">{value.toLocaleString()}</span>
      )}
    </div>
  )
}

function PlanLimitsEditor({ isSuperAdmin }: { isSuperAdmin: boolean }) {
  const planLimitsQuery = usePlanLimits()
  const updatePlanLimits = useUpdatePlanLimits()

  const [localLimits, setLocalLimits] = useState<PlanLimits>({ free: 3, pro: 25, agency: 500 })

  useEffect(() => {
    if (planLimitsQuery.data) setLocalLimits(planLimitsQuery.data)
  }, [planLimitsQuery.data])

  const plans: { key: keyof PlanLimits; label: string; badge: string }[] = [
    { key: "free", label: "Free", badge: "bg-muted/50 text-foreground/80 border-0" },
    { key: "pro", label: "Pro", badge: "bg-indigo-100 text-indigo-700 border-0" },
    { key: "agency", label: "Agency", badge: "bg-purple-100 text-purple-700 border-0" },
  ]

  if (planLimitsQuery.isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 3 }).map((_, i) => <Skeleton key={i} className="h-10 w-full rounded-lg" />)}
      </div>
    )
  }

  return (
    <div className="space-y-3">
      {plans.map(({ key, label, badge }) => (
        <div key={key} className="flex items-center justify-between rounded-lg bg-muted/40 px-4 py-2.5 gap-3">
          <Badge className={`text-xs px-2 py-0.5 shrink-0 ${badge}`}>{label}</Badge>
          {isSuperAdmin ? (
            <div className="flex items-center gap-2 ml-auto">
              <Input
                type="number"
                value={localLimits[key]}
                onChange={(e) => {
                  const val = parseInt(e.target.value, 10)
                  if (!isNaN(val) && val >= 1 && val <= 10000) {
                    setLocalLimits((prev) => ({ ...prev, [key]: val }))
                  }
                }}
                min={1}
                max={10000}
                className="w-24 h-7 text-sm text-right tabular-nums"
                aria-label={`${label} scan limit`}
              />
              <span className="text-xs text-muted-foreground whitespace-nowrap">scans / mo</span>
            </div>
          ) : (
            <span className="text-sm font-semibold text-foreground tabular-nums ml-auto">
              {localLimits[key]} scans / month
            </span>
          )}
        </div>
      ))}
      {isSuperAdmin && (
        <Button size="sm" className="w-full mt-2" onClick={() => updatePlanLimits.mutate(localLimits)} disabled={updatePlanLimits.isPending}>
          {updatePlanLimits.isPending ? (
            <><Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />Saving…</>
          ) : (
            <><Save className="mr-2 h-3.5 w-3.5" />Save Plan Limits</>
          )}
        </Button>
      )}
    </div>
  )
}

function PillarWeightsEditor({ isSuperAdmin }: { isSuperAdmin: boolean }) {
  const pillarWeightsQuery = usePillarWeights()
  const updatePillarWeights = useUpdatePillarWeights()

  const [localWeights, setLocalWeights] = useState<Record<string, number>>({
    value_proposition: 25,
    cta_effectiveness: 20,
    trust_signals: 15,
    visual_hierarchy: 15,
    mobile_experience: 10,
    content_copy: 10,
    page_performance: 5,
  })

  useEffect(() => {
    if (pillarWeightsQuery.data) {
      const percentages: Record<string, number> = {}
      for (const [key, val] of Object.entries(pillarWeightsQuery.data)) {
        percentages[key] = Math.round(val * 100)
      }
      setLocalWeights(percentages)
    }
  }, [pillarWeightsQuery.data])

  const totalPercent = Object.values(localWeights).reduce((s, v) => s + v, 0)
  const totalOk = totalPercent === 100

  const handleSave = () => {
    const decimals: Record<string, number> = {}
    for (const [key, val] of Object.entries(localWeights)) {
      decimals[key] = val / 100
    }
    updatePillarWeights.mutate(decimals)
  }

  if (pillarWeightsQuery.isLoading) {
    return (
      <div className="space-y-1.5">
        {Array.from({ length: 7 }).map((_, i) => <Skeleton key={i} className="h-7 w-full rounded" />)}
      </div>
    )
  }

  return (
    <div className="space-y-2">
      {PILLAR_DEFINITIONS.map((pillar) => {
        const pct = localWeights[pillar.key] ?? 0
        return (
          <div key={pillar.key} className="flex items-center justify-between gap-3">
            <span className="text-xs text-muted-foreground flex-1 truncate">{pillar.label}</span>
            {isSuperAdmin ? (
              <div className="flex items-center gap-1.5">
                <Input
                  type="number"
                  value={pct}
                  onChange={(e) => {
                    const val = parseInt(e.target.value, 10)
                    if (!isNaN(val) && val >= 0 && val <= 100) {
                      setLocalWeights((prev) => ({ ...prev, [pillar.key]: val }))
                    }
                  }}
                  min={0}
                  max={100}
                  className="w-16 h-7 text-xs text-right tabular-nums"
                  aria-label={`${pillar.label} weight %`}
                />
                <span className="text-xs text-muted-foreground">%</span>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <div className="w-24 h-1.5 rounded-full bg-muted/50 overflow-hidden">
                  <div className="h-full rounded-full bg-primary/60" style={{ width: `${pct}%` }} />
                </div>
                <span className="text-xs font-medium text-muted-foreground w-8 text-right tabular-nums">{pct}%</span>
              </div>
            )}
          </div>
        )
      })}

      {isSuperAdmin && (
        <>
          <div className={cn(
            "flex items-center justify-between rounded-lg px-3 py-2 mt-2 text-xs font-medium",
            totalOk ? "bg-green-50 text-green-700" : "bg-red-50 text-red-700"
          )}>
            <span>Total</span>
            <span className="tabular-nums">{totalPercent}%</span>
          </div>
          <Button
            size="sm"
            className="w-full mt-1"
            onClick={handleSave}
            disabled={!totalOk || updatePillarWeights.isPending}
            title={totalOk ? undefined : "Weights must sum to exactly 100%"}
          >
            {updatePillarWeights.isPending ? (
              <><Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />Saving…</>
            ) : (
              <><Save className="mr-2 h-3.5 w-3.5" />Save Pillar Weights</>
            )}
          </Button>
        </>
      )}
    </div>
  )
}

