import { useAuditLog } from "@/hooks/admin/use-audit-log"
import { formatDistanceToNow, format } from "date-fns"

const PAGE_SIZE = 25

const ACTION_OPTIONS = [
  { value: "all", label: "All actions" },
  { value: "change_plan", label: "Change Plan" },
  { value: "change_role", label: "Change Role" },
  { value: "reset_scan_count", label: "Reset Scan Count" },
  { value: "ban_user", label: "Ban User" },
  { value: "unban_user", label: "Unban User" },
]

const ACTION_LABELS: Record<string, string> = {
  change_plan: "Changed plan",
  change_role: "Changed role",
  reset_scan_count: "Reset scan count",
  ban_user: "Banned user",
  unban_user: "Unbanned user",
}

const ACTION_BADGE_CLASSES: Record<string, string> = {
  change_plan: "bg-blue-100 text-blue-700 border-0",
  change_role: "bg-purple-100 text-purple-700 border-0",
  reset_scan_count: "bg-amber-100 text-amber-700 border-0",
  ban_user: "bg-red-100 text-red-700 border-0",
  unban_user: "bg-green-100 text-green-700 border-0",
}

function MetadataPill({ label, value }: { label: string; value: string }) {
  return (
    <span className="inline-flex items-center gap-1 rounded bg-muted/50 px-1.5 py-0.5 text-[10px] font-medium text-foreground/80">
      <span className="text-muted-foreground">{label}:</span>
      <span className="capitalize">{String(value).replace("_", " ")}</span>
