export default function AdminFeatureFlags() {
  const flagsQuery = useFeatureFlags()
  const updateFlag = useUpdateFeatureFlag()

  const flags = flagsQuery.data?.flags ?? {}
  const updatedAt = flagsQuery.data?.updatedAt ?? null

  const handleToggle = (flag: FlagDefinition, enabled: boolean) => {
    if (updateFlag.isPending) return
    updateFlag.mutate(
      { key: flag.key, enabled, currentFlags: flags },
      {
        onError: () => {
          toast.error(`Failed to toggle ${flag.label}. Please try again.`)
        },
      }
    )
  }

  const categories: FlagDefinition["category"][] = ["ui", "feature", "system"]

  return (
    <div className="space-y-8">
      <PageHeader
        title="Feature Flags"
        description="Toggle features on/off across the platform. Changes take effect immediately for all users."
      />

      <div
        role="status"
        className="flex items-start gap-3 rounded-xl border border-green-200 bg-green-50 px-4 py-3.5"
      >
        <CheckCircle2 className="h-4 w-4 text-green-500 mt-0.5 shrink-0" />
        <div className="flex-1">
          <p className="text-sm font-medium text-green-800">Flags stored in database</p>
          <p className="text-xs text-green-700 mt-0.5">
            Feature flags are stored in{" "}
            <code className="font-mono text-xs bg-green-100 px-1 py-0.5 rounded">system_config</code>{" "}
            and apply platform-wide immediately.
            {updatedAt && (
              <span className="ml-1">
                Last updated {format(new Date(updatedAt), "MMM d, yyyy 'at' h:mm a")}.
              </span>
            )}
          </p>
        </div>
      </div>

      {flagsQuery.isLoading ? (
        <FlagsSkeleton />
      ) : flagsQuery.isError ? (
        <div role="alert" className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">
          Failed to load feature flags. Check your admin permissions.
        </div>
      ) : (
        categories.map((category) => {
          const categoryFlags = FLAG_DEFINITIONS.filter((f) => f.category === category)

          return (
            <Card key={category} className="border-border/50 shadow-sm">
              <CardHeader className="pb-3">
                <div className="flex items-center gap-2">
                  <Flag className="h-4 w-4 text-muted-foreground" />
                  <CardTitle className="text-base font-semibold capitalize">
                    {category === "ui" ? "UI Visibility" : category === "feature" ? "Feature Toggles" : "System Flags"}
                  </CardTitle>
                </div>
              </CardHeader>
              <CardContent className="divide-y divide-slate-100">
                {categoryFlags.map((flag) => {
                  const enabled = flags[flag.key] ?? flag.defaultValue
                  const isPending = updateFlag.isPending && updateFlag.variables?.key === flag.key

                  return (
                    <div key={flag.key} className="flex items-start gap-4 py-4 first:pt-0 last:pb-0">
                      <div className="pt-0.5">
                        <Switch
                          id={flag.key}
                          checked={enabled}
                          onCheckedChange={(v) => handleToggle(flag, v)}
                          disabled={isPending || updateFlag.isPending}
                          aria-label={`Toggle ${flag.label}`}
                        />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <Label htmlFor={flag.key} className="text-sm font-medium cursor-pointer">
                            {flag.label}
                          </Label>
                          <Badge className={`text-[10px] px-1.5 py-0 ${CATEGORY_BADGE_CLASSES[flag.category]}`}>
                            {CATEGORY_LABELS[flag.category]}
                          </Badge>
                          {flag.requiresSuperAdmin && (
                            <Badge className="bg-red-50 text-red-600 border-red-200 text-[10px] px-1.5 py-0">
                              Super Admin
                            </Badge>
                          )}
                        </div>
                        <p className="mt-1 text-xs text-muted-foreground leading-relaxed">{flag.description}</p>
                        {updatedAt && (
                          <div className="mt-1.5 flex items-center gap-1 text-[10px] text-muted-foreground/60">
                            <Clock className="h-2.5 w-2.5" />
                            <span>Last changed {format(new Date(updatedAt), "MMM d, yyyy 'at' h:mm a")}</span>
                          </div>
                        )}
                      </div>
                      <div className="shrink-0 pt-0.5">
                        {isPending ? (
                          <Badge className="bg-muted/50 text-slate-500 border-0 text-xs animate-pulse">Saving…</Badge>
                        ) : (
                          <Badge className={enabled ? "bg-green-100 text-green-700 border-0 text-xs" : "bg-muted/50 text-slate-500 border-0 text-xs"}>
                            {enabled ? "On" : "Off"}
                          </Badge>
                        )}
                      </div>
                    </div>
                  )
                })}
              </CardContent>
            </Card>
          )
        })
      )}
    </div>
  )
}
